-- V1 (scenario-service T2; spec docs/specs/scenario-service.md D14, ERD group scenario_service): the whole schema.
-- Database pattern for every service: ids are uuid generated by the application; timestamps are timestamptz set by
-- the application from the service clock (no database defaults); enums are varchar(32) with a CHECK listing the Java
-- constants (ERD-D12); JSON is jsonb; every foreign-key column leads an index.
-- Named deviation (D14): the parsed-structure tables cascade from their parent, because each save replaces the
-- current version's structure. Versions and tag catalogue rows are never removed by a cascade (ON DELETE RESTRICT).
-- Text unique indexes hash the compared value with md5, because valid paths (1,024 characters of up to 4 bytes) and
-- tags exceed PostgreSQL's 2,704-byte B-tree entry limit (user decision 2026-10-18, option A). Equal values have
-- equal hashes, so uniqueness is never weaker; lookups compare the same md5 expression plus the value itself.

CREATE TABLE features
(
    id              uuid                     NOT NULL,
    project_id      uuid                     NOT NULL,
    path            varchar(1024)            NOT NULL,
    name            text                     NOT NULL,
    description     text                     NOT NULL,
    language        varchar(10)              NOT NULL,
    current_version integer                  NOT NULL,
    created_by      uuid                     NOT NULL,
    updated_by      uuid                     NOT NULL,
    archived_at     timestamp with time zone,
    created_at      timestamp with time zone NOT NULL,
    updated_at      timestamp with time zone NOT NULL,
    CONSTRAINT pk_features PRIMARY KEY (id)
);

-- Paths are unique per project among active features, compared by ICU root lower case (D10): the builtin C.UTF-8
-- lower() maps U+0130 differently from Java's toLowerCase(Locale.ROOT); und-x-icu agrees with it.
CREATE UNIQUE INDEX uk_features_project_id_path_lower
    ON features (project_id, md5(lower(path COLLATE "und-x-icu"))) WHERE archived_at IS NULL;
-- The feature list per project, archived features included (the partial unique index covers active ones only).
CREATE INDEX ix_features_project_id ON features (project_id);

CREATE TABLE feature_versions
(
    id           uuid                     NOT NULL,
    feature_id   uuid                     NOT NULL,
    version      integer                  NOT NULL,
    source       text                     NOT NULL,
    content_hash varchar(64)              NOT NULL,
    message      varchar(500),
    created_by   uuid                     NOT NULL,
    created_at   timestamp with time zone NOT NULL,
    CONSTRAINT pk_feature_versions PRIMARY KEY (id),
    CONSTRAINT uk_feature_versions_feature_id_version UNIQUE (feature_id, version),
    CONSTRAINT fk_feature_versions_feature_id FOREIGN KEY (feature_id) REFERENCES features (id) ON DELETE RESTRICT
);

CREATE TABLE rules
(
    id           uuid                     NOT NULL,
    feature_id   uuid                     NOT NULL,
    keyword_text text                     NOT NULL,
    name         text                     NOT NULL,
    description  text                     NOT NULL,
    position     integer                  NOT NULL,
    line         integer                  NOT NULL,
    created_at   timestamp with time zone NOT NULL,
    updated_at   timestamp with time zone NOT NULL,
    CONSTRAINT pk_rules PRIMARY KEY (id),
    CONSTRAINT fk_rules_feature_id FOREIGN KEY (feature_id) REFERENCES features (id) ON DELETE CASCADE
);

CREATE INDEX ix_rules_feature_id ON rules (feature_id);

CREATE TABLE scenarios
(
    id           uuid                     NOT NULL,
    feature_id   uuid                     NOT NULL,
    rule_id      uuid,
    kind         varchar(32)              NOT NULL,
    keyword_text text                     NOT NULL,
    name         text                     NOT NULL,
    description  text                     NOT NULL,
    position     integer                  NOT NULL,
    line         integer                  NOT NULL,
    created_at   timestamp with time zone NOT NULL,
    updated_at   timestamp with time zone NOT NULL,
    CONSTRAINT pk_scenarios PRIMARY KEY (id),
    CONSTRAINT ck_scenarios_kind_values CHECK (kind IN ('BACKGROUND', 'SCENARIO', 'SCENARIO_OUTLINE')),
    CONSTRAINT fk_scenarios_feature_id FOREIGN KEY (feature_id) REFERENCES features (id) ON DELETE CASCADE,
    CONSTRAINT fk_scenarios_rule_id FOREIGN KEY (rule_id) REFERENCES rules (id) ON DELETE CASCADE
);

CREATE INDEX ix_scenarios_feature_id ON scenarios (feature_id);
CREATE INDEX ix_scenarios_rule_id ON scenarios (rule_id);

CREATE TABLE steps
(
    id                    uuid                     NOT NULL,
    scenario_id           uuid                     NOT NULL,
    position              integer                  NOT NULL,
    keyword               varchar(32)              NOT NULL,
    keyword_text          text                     NOT NULL,
    step_text             text                     NOT NULL,
    argument_type         varchar(32)              NOT NULL,
    data_table            jsonb,
    doc_string            text,
    doc_string_media_type text,
    line                  integer                  NOT NULL,
    created_at            timestamp with time zone NOT NULL,
    updated_at            timestamp with time zone NOT NULL,
    CONSTRAINT pk_steps PRIMARY KEY (id),
    CONSTRAINT ck_steps_keyword_values CHECK (keyword IN ('GIVEN', 'WHEN', 'THEN', 'AND', 'BUT', 'ASTERISK')),
    CONSTRAINT ck_steps_argument_type_values CHECK (argument_type IN ('NONE', 'DATA_TABLE', 'DOC_STRING')),
    CONSTRAINT fk_steps_scenario_id FOREIGN KEY (scenario_id) REFERENCES scenarios (id) ON DELETE CASCADE
);

CREATE INDEX ix_steps_scenario_id ON steps (scenario_id);

CREATE TABLE examples
(
    id           uuid                     NOT NULL,
    scenario_id  uuid                     NOT NULL,
    keyword_text text                     NOT NULL,
    name         text                     NOT NULL,
    description  text                     NOT NULL,
    position     integer                  NOT NULL,
    header       jsonb                    NOT NULL,
    line         integer                  NOT NULL,
    created_at   timestamp with time zone NOT NULL,
    updated_at   timestamp with time zone NOT NULL,
    CONSTRAINT pk_examples PRIMARY KEY (id),
    CONSTRAINT fk_examples_scenario_id FOREIGN KEY (scenario_id) REFERENCES scenarios (id) ON DELETE CASCADE
);

CREATE INDEX ix_examples_scenario_id ON examples (scenario_id);

CREATE TABLE example_rows
(
    id          uuid                     NOT NULL,
    examples_id uuid                     NOT NULL,
    position    integer                  NOT NULL,
    cells       jsonb                    NOT NULL,
    line        integer                  NOT NULL,
    created_at  timestamp with time zone NOT NULL,
    updated_at  timestamp with time zone NOT NULL,
    CONSTRAINT pk_example_rows PRIMARY KEY (id),
    CONSTRAINT fk_example_rows_examples_id FOREIGN KEY (examples_id) REFERENCES examples (id) ON DELETE CASCADE
);

CREATE INDEX ix_example_rows_examples_id ON example_rows (examples_id);

CREATE TABLE tags
(
    id         uuid                     NOT NULL,
    project_id uuid                     NOT NULL,
    name       text                     NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_tags PRIMARY KEY (id)
);

-- Tags are unique per project, compared exactly (case-sensitive, D12); its leading project_id also serves lookups.
CREATE UNIQUE INDEX uk_tags_project_id_name ON tags (project_id, md5(name));

CREATE TABLE tag_assignments
(
    id          uuid                     NOT NULL,
    tag_id      uuid                     NOT NULL,
    feature_id  uuid                     NOT NULL,
    target_type varchar(32)              NOT NULL,
    target_id   uuid                     NOT NULL,
    created_at  timestamp with time zone NOT NULL,
    CONSTRAINT pk_tag_assignments PRIMARY KEY (id),
    CONSTRAINT uk_tag_assignments_tag_id_target_type_target_id UNIQUE (tag_id, target_type, target_id),
    CONSTRAINT ck_tag_assignments_target_type_values CHECK (target_type IN ('FEATURE', 'RULE', 'SCENARIO', 'EXAMPLES')),
    CONSTRAINT fk_tag_assignments_tag_id FOREIGN KEY (tag_id) REFERENCES tags (id) ON DELETE RESTRICT,
    CONSTRAINT fk_tag_assignments_feature_id FOREIGN KEY (feature_id) REFERENCES features (id) ON DELETE CASCADE
);

CREATE INDEX ix_tag_assignments_target_type_target_id ON tag_assignments (target_type, target_id);
CREATE INDEX ix_tag_assignments_feature_id_tag_id ON tag_assignments (feature_id, tag_id);
